std::tuple<torch::Tensor, torch::Tensor> adafactor_row_col_mean_square(
    torch::Tensor grad,
    double eps
) {
    TORCH_CHECK(grad.is_cuda() && grad.is_contiguous(),
                "adafactor_row_col_mean_square: grad must be a contiguous CUDA tensor");
    int grad_dtype = float_dtype_code(grad, "adafactor_row_col_mean_square: grad");
    TORCH_CHECK(grad.dim() == 2, "adafactor_row_col_mean_square: grad must be 2-D");
    TORCH_CHECK(eps >= 0.0, "adafactor_row_col_mean_square: eps must be non-negative");

    int64_t rows = grad.size(0);
    int64_t cols = grad.size(1);
    TORCH_CHECK(rows > 0 && cols > 0, "adafactor_row_col_mean_square: grad dimensions must be non-empty");
    TORCH_CHECK(rows <= (int64_t)0xFFFFFFFFu && cols <= (int64_t)0xFFFFFFFFu,
                "adafactor_row_col_mean_square: dimensions exceed HIP grid limit");

    auto row = torch::empty({rows}, grad.options().dtype(torch::kFloat32));
    auto col = torch::empty({cols}, grad.options().dtype(torch::kFloat32));
    launch_adafactor_row_col_mean_square(
        grad.data_ptr(), row.data_ptr<float>(), col.data_ptr<float>(),
        rows, cols, grad_dtype, (float)eps, current_stream());
    return std::make_tuple(row, col);
}

// ---------------------------------------------------------------------------
// Phase 4 — fp8_linear_forward
// input : [M, K] float32
// weight: [N, K] float32  (computes input @ weight.T)
// bias  : [N]    float32  (optional)
// returns [M, N] float32
// ---------------------------------------------------------------------------
torch::Tensor fp8_linear_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias
) {
    TORCH_CHECK(input.is_cuda()  && input.is_contiguous(),
                "fp8_linear_forward: input must be a contiguous CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && weight.is_contiguous(),
                "fp8_linear_forward: weight must be a contiguous CUDA tensor");
    int input_dtype = float_dtype_code(input, "fp8_linear_forward: input");
    int weight_dtype = float_dtype_code(weight, "fp8_linear_forward: weight");
    TORCH_CHECK(input.dim()  == 2, "fp8_linear_forward: input must be 2-D");
    TORCH_CHECK(weight.dim() == 2, "fp8_linear_forward: weight must be 2-D");

    int64_t M = input.size(0);
    int64_t K = input.size(1);
    int64_t N = weight.size(0);
    TORCH_CHECK(weight.size(1) == K,
                "fp8_linear_forward: weight K-dim mismatch");

    // Bug 2: guard int64 → int narrowing
    int iM = checked_int(M, "M");
    int iN = checked_int(N, "N");
    int iK = checked_int(K, "K");

    // Bug 3: guard HW grid dimension limits
    check_grid_dim(M, 16, "M (rows)");
    check_grid_dim(N, 16, "N (cols)");

    // Hazard B: both tensors must be on the same device
    TORCH_CHECK(input.device() == weight.device(),
                "fp8_linear_forward: input and weight must be on the same device");
    check_gfx12_fp8_wmma_runtime("fp8_linear_forward");

    BiasLaunch bias_launch = validate_bias_for_forward(bias, N, input.device(), "fp8_linear_forward");
    auto output = torch::empty({M, N}, input.options());
    launch_fp8_linear_forward(
        input.data_ptr(),
        weight.data_ptr(),
        output.data_ptr(),
        bias_launch.ptr,
        iM, iN, iK, input_dtype, weight_dtype, input_dtype,
        bias_launch.dtype, bias_launch.has_bias,
        current_stream()
    );

    return output;
}

