torch::Tensor pack_fp8_weight_for_wmma(torch::Tensor weight_fp8) {
    TORCH_CHECK(weight_fp8.is_cuda() && weight_fp8.is_contiguous(),
                "pack_fp8_weight_for_wmma: weight_fp8 must be a contiguous CUDA tensor");
    TORCH_CHECK(weight_fp8.scalar_type() == torch::kUInt8,
                "pack_fp8_weight_for_wmma: weight_fp8 must be uint8");
    TORCH_CHECK(weight_fp8.dim() == 2,
                "pack_fp8_weight_for_wmma: weight_fp8 must be 2-D [N, K]");

    int64_t N = weight_fp8.size(0);
    int64_t K = weight_fp8.size(1);
    TORCH_CHECK(N > 0 && K > 0,
                "pack_fp8_weight_for_wmma: weight dimensions must be non-empty");
    int64_t n_tiles = (N + 15) / 16;
    int64_t k_tiles = (K + 15) / 16;
    int iN = checked_int(N, "N");
    int iK = checked_int(K, "K");
    int iNT = checked_int(n_tiles, "n_tiles");
    int iKT = checked_int(k_tiles, "k_tiles");
    TORCH_CHECK(n_tiles == 0 || n_tiles <= (int64_t)0xFFFFFFFFu / k_tiles / 256,
                "pack_fp8_weight_for_wmma: packed grid exceeds HIP dim3 limit");

    auto packed = torch::empty({n_tiles, k_tiles, 2, 16, 8}, weight_fp8.options());
    launch_pack_fp8_weight_for_wmma(
        weight_fp8.data_ptr<uint8_t>(), packed.data_ptr<uint8_t>(),
        iN, iK, iNT, iKT, current_stream());
    return packed;
}

