torch::Tensor fast_rms_norm_forward(
    torch::Tensor x,
    torch::Tensor w,
    double eps
) {
    TORCH_CHECK(x.is_cuda() && x.is_contiguous(), "fast_rms_norm_forward: x must be contiguous CUDA tensor");
    TORCH_CHECK(w.is_cuda() && w.is_contiguous(), "fast_rms_norm_forward: w must be contiguous CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kHalf && w.scalar_type() == torch::kHalf,
                "fast_rms_norm_forward: x/w must be FP16 (kernel reinterprets bits as half)");

    auto y = torch::empty_like(x);
    int D = (int)w.numel();
    TORCH_CHECK(D > 0 && x.numel() % D == 0, "fast_rms_norm_forward: x.numel() (", x.numel(),
                ") must be a multiple of w.numel() (", D, ")");
    int rows = (int)(x.numel() / D);
    launch_fast_rms_norm(
        x.data_ptr(),
        w.data_ptr(),
        y.data_ptr(),
        rows,
        D,
        (float)eps,
        current_stream()
    );
    return y;
}

torch::Tensor fast_rms_norm_gated_forward(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor gate,
    int64_t num_heads,
    int64_t head_dim,
    double eps
) {
    TORCH_CHECK(x.is_cuda() && x.is_contiguous(), "fast_rms_norm_gated_forward: x must be contiguous CUDA tensor");
    TORCH_CHECK(w.is_cuda() && w.is_contiguous(), "fast_rms_norm_gated_forward: w must be contiguous CUDA tensor");
    TORCH_CHECK(gate.is_cuda() && gate.is_contiguous(), "fast_rms_norm_gated_forward: gate must be contiguous CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kHalf && w.scalar_type() == torch::kHalf && gate.scalar_type() == torch::kHalf,
                "fast_rms_norm_gated_forward: x/w/gate must be FP16 (kernel reinterprets bits as half)");
    const int64_t full = num_heads * head_dim;
    TORCH_CHECK(x.numel() == full, "fast_rms_norm_gated_forward: x must hold num_heads*head_dim elements, got ",
                x.numel(), " for heads=", num_heads, " dim=", head_dim);
    TORCH_CHECK(gate.numel() == full, "fast_rms_norm_gated_forward: gate must hold num_heads*head_dim elements, got ",
                gate.numel());
    // w is either per-head [num_heads, head_dim] or shared [head_dim] (broadcast).
    // Anything else used to silently read out of bounds for heads >= 1.
    int w_stride = -1;
    if (w.numel() == full) {
        w_stride = (int)head_dim;
    } else if (w.numel() == head_dim) {
        w_stride = 0;
    }
    TORCH_CHECK(w_stride >= 0, "fast_rms_norm_gated_forward: w must be [head_dim] shared or [num_heads, head_dim], got ",
                w.numel(), " elements for heads=", num_heads, " dim=", head_dim);

    auto y = torch::empty_like(x);
    launch_fast_rms_norm_gated(
        x.data_ptr(),
        w.data_ptr(),
        gate.data_ptr(),
        y.data_ptr(),
        (int)num_heads,
        (int)head_dim,
        (float)eps,
        w_stride,
        current_stream()
    );
    return y;
}

torch::Tensor fp8_linear_forward_blockwise(
    torch::Tensor input_fp8,
    torch::Tensor input_scales,
    torch::Tensor weight_fp8,
    torch::Tensor weight_scales,
    torch::Tensor output_dtype_source,
    int64_t block_size,
    c10::optional<torch::Tensor> bias
) {
    TORCH_CHECK(input_fp8.is_cuda() && input_fp8.is_contiguous(),
                "fp8_linear_forward_blockwise: input_fp8 must be a contiguous CUDA tensor");
    TORCH_CHECK(input_scales.is_cuda() && input_scales.is_contiguous(),
                "fp8_linear_forward_blockwise: input_scales must be a contiguous CUDA tensor");
    TORCH_CHECK(weight_fp8.is_cuda() && weight_fp8.is_contiguous(),
                "fp8_linear_forward_blockwise: weight_fp8 must be a contiguous CUDA tensor");
    TORCH_CHECK(weight_scales.is_cuda() && weight_scales.is_contiguous(),
                "fp8_linear_forward_blockwise: weight_scales must be a contiguous CUDA tensor");
    TORCH_CHECK(output_dtype_source.is_cuda(),
                "fp8_linear_forward_blockwise: output_dtype_source must be a CUDA tensor");
    TORCH_CHECK(input_fp8.scalar_type() == torch::kUInt8 && weight_fp8.scalar_type() == torch::kUInt8,
                "fp8_linear_forward_blockwise: FP8 inputs must be uint8");
    TORCH_CHECK(input_scales.scalar_type() == torch::kFloat32 && weight_scales.scalar_type() == torch::kFloat32,
                "fp8_linear_forward_blockwise: scales must be float32");
    int output_dtype = float_dtype_code(output_dtype_source, "fp8_linear_forward_blockwise: output_dtype_source");
    int iBlock = checked_block_size(block_size, "fp8_linear_forward_blockwise");

    TORCH_CHECK(input_fp8.dim() == 2 && weight_fp8.dim() == 2,
                "fp8_linear_forward_blockwise: input_fp8 and weight_fp8 must be 2-D");
    TORCH_CHECK(input_scales.dim() == 2 && weight_scales.dim() == 2,
                "fp8_linear_forward_blockwise: scales must be 2-D");

    int64_t M = input_fp8.size(0);
    int64_t K = input_fp8.size(1);
    int64_t N = weight_fp8.size(0);
    TORCH_CHECK(weight_fp8.size(1) == K,
                "fp8_linear_forward_blockwise: weight K-dim mismatch");
    int64_t blocks_per_row = (K + block_size - 1) / block_size;
    TORCH_CHECK(input_scales.size(0) == M && input_scales.size(1) == blocks_per_row,
                "fp8_linear_forward_blockwise: input_scales shape mismatch");
    TORCH_CHECK(weight_scales.size(0) == N && weight_scales.size(1) == blocks_per_row,
                "fp8_linear_forward_blockwise: weight_scales shape mismatch");
    TORCH_CHECK(input_fp8.device() == input_scales.device() && input_fp8.device() == weight_fp8.device() &&
                input_fp8.device() == weight_scales.device() && input_fp8.device() == output_dtype_source.device(),
                "fp8_linear_forward_blockwise: all tensors must be on the same device");
    TORCH_CHECK(M == 0 || M <= (int64_t)INT_MAX,
                "fp8_linear_forward_blockwise: M exceeds INT_MAX");
    int iM = checked_int(M, "M");
    int iN = checked_int(N, "N");
    int iK = checked_int(K, "K");
    int iBlocks = checked_int(blocks_per_row, "blocks_per_row");
    TORCH_CHECK(M == 0 || N <= ((int64_t)0xFFFFFFFFu * 256 / M),
                "fp8_linear_forward_blockwise: output grid exceeds HIP dim3 limit");

    BiasLaunch bias_launch = validate_bias_for_forward(bias, N, input_fp8.device(), "fp8_linear_forward_blockwise");
    auto output = torch::empty({M, N}, output_dtype_source.options());
    launch_fp8_linear_forward_blockwise(
        input_fp8.data_ptr<uint8_t>(), input_scales.data_ptr<float>(),
        weight_fp8.data_ptr<uint8_t>(), weight_scales.data_ptr<float>(),
        output.data_ptr(), bias_launch.ptr,
        iM, iN, iK, iBlocks, iBlock,
        output_dtype, bias_launch.dtype, bias_launch.has_bias, current_stream());
    return output;
}

// ---------------------------------------------------------------------------
// Phase 4 — fp8_linear_backward_input
// grad_output: [M, N] float32
// weight      : [N, K] float32
// returns grad_input: [M, K] float32
// ---------------------------------------------------------------------------
torch::Tensor fp8_linear_backward_input(
    torch::Tensor grad_output,
    torch::Tensor weight
) {
    TORCH_CHECK(grad_output.is_cuda() && grad_output.is_contiguous(),
                "fp8_linear_backward_input: grad_output must be contiguous CUDA");
    TORCH_CHECK(weight.is_cuda()      && weight.is_contiguous(),
                "fp8_linear_backward_input: weight must be contiguous CUDA");
    int grad_output_dtype = float_dtype_code(grad_output, "fp8_linear_backward_input: grad_output");
    int weight_dtype = float_dtype_code(weight, "fp8_linear_backward_input: weight");

    int64_t M = grad_output.size(0);
    int64_t N = grad_output.size(1);
    int64_t K = weight.size(1);
    TORCH_CHECK(weight.size(0) == N,
                "fp8_linear_backward_input: grad_output / weight N-dim mismatch");

    // Bug 2: guard int64 → int narrowing
    int iM = checked_int(M, "M");
    int iN = checked_int(N, "N");
    int iK = checked_int(K, "K");

    // Bug 3: guard HW grid dimension limits
    check_grid_dim(M, 16, "M (rows)");
    check_grid_dim(K, 16, "K (cols)");

    // Hazard B: grad_output and weight must be on the same device
    TORCH_CHECK(grad_output.device() == weight.device(),
                "fp8_linear_backward_input: grad_output and weight must be on the same device");
    check_gfx12_fp8_wmma_runtime("fp8_linear_backward_input");

    auto grad_input = torch::empty({M, K}, grad_output.options());
    launch_fp8_linear_backward_input(
        grad_output.data_ptr(),
        weight.data_ptr(),
        grad_input.data_ptr(),
        iM, iN, iK, grad_output_dtype, weight_dtype, grad_output_dtype,
        current_stream()
    );
    return grad_input;
}

